package dev.cosmerearcanists.power;
import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.*;
import dev.cosmerearcanists.compounding.*;
import dev.cosmerearcanists.connection.*;
import dev.cosmerearcanists.equipment.*;
import dev.cosmerearcanists.feruchemy.Metalminds;
import dev.cosmerearcanists.hemalurgy.*;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.event.entity.living.LivingDeathEvent;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class DuraluminSpikeGameTests {
    private static final Map<net.minecraft.server.level.ServerPlayer,List<StolenConnection>> IMPLANTED=new WeakHashMap<>();
    private static final Map<net.minecraft.server.level.ServerPlayer,Map<String,List<IdentityMath.Portion>>> EXTERNAL=new WeakHashMap<>();
    static{IdentityAccess.registerImplanted(p->IMPLANTED.getOrDefault(p,List.of()));PowerSources.registerExternal((p,key)->EXTERNAL.getOrDefault(p,Map.of()).getOrDefault(key,List.of()));}
    private static FakePlayer player(GameTestHelper h){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"IdentityTest"));p.setGameMode(GameType.SURVIVAL);PowerAttributes.migrate(p);return p;}
    private static ItemStack equip(FakePlayer p){var s=new ItemStack(EquipmentContent.SPIKES.get("duralumin").get());p.setItemInHand(InteractionHand.MAIN_HAND,s);return s;}
    private static LivingDeathEvent queue(FakePlayer p,net.minecraft.world.entity.LivingEntity victim){victim.setHealth(0);var e=new LivingDeathEvent(victim,p.damageSources().playerAttack(p));HemalurgyService.capture(e);return e;}
    @GameTest(template="empty") public static void extractionMovesConnectionsHomeAndIdentityButPreservesPowerProvenance(GameTestHelper h){var p=player(h);var donor=player(h);var friend=UUID.randomUUID();new OriginData("sel","human","none","none").save(donor);PowerAttributes.set(donor,"a:steel",1);var data=ConnectionBonds.get(p.server);data.ledger.restore(new ConnectionLedger.Pair(donor.getUUID(),friend),new ConnectionLedger.Bond(60,0,0));var oldMind=new ItemStack(Items.IRON_INGOT);Metalminds.transfer(oldMind,donor.getUUID(),"iron",20);var spike=equip(p);queue(p,donor);HemalurgyService.flush();var charge=HemalurgicSpikes.contents(spike);h.assertTrue(charge!=null&&charge.connection().identity().equals(donor.getUUID())&&charge.connection().homeWorld().equals("sel")&&charge.connection().players().get(friend)==60,"Full original Identity/home/bond strength stored");h.assertTrue(data.ledger.connections(donor.getUUID()).isEmpty()&&data.ledger.connections(friend).isEmpty()&&IdentityAccess.nativeWorld(donor).isEmpty(),"Connections are stolen, not left on the respawned donor");h.assertTrue(!IdentityAccess.nativeIdentity(donor).equals(donor.getUUID())&&PowerSources.personal(donor,"a:steel").getFirst().identity().equals(donor.getUUID())&&PowerAttributes.baseStrength(donor,"a:steel")==1,"New native Identity does not rewrite or erase existing power provenance");h.assertTrue(!Metalminds.usableBy(oldMind,donor,"iron"),"Donor loses access to the stolen Identity's old keyed mind");var newMind=new ItemStack(Items.IRON_INGOT);Metalminds.transferFor(newMind,donor,"iron",10);h.assertTrue(Metalminds.owner(newMind).equals(IdentityAccess.nativeIdentity(donor)),"New stores use the replacement spiritual Identity");var restored=ItemStack.parseOptional(h.getLevel().registryAccess(),(net.minecraft.nbt.CompoundTag)spike.save(h.getLevel().registryAccess()));h.assertTrue(charge.equals(HemalurgicSpikes.contents(restored)),"Connection snapshot survives serialization");h.assertTrue(!IdentityAccess.accepts(p,donor.getUUID())&&!IdentityAccess.worlds(p).contains("sel"),"Holding a charged duralumin spike does not activate implantation");var clone=player(h);PowerData.clonePlayer(donor,clone);OriginData.copy(donor,clone);h.assertTrue(IdentityAccess.nativeIdentity(clone).equals(IdentityAccess.nativeIdentity(donor))&&IdentityAccess.nativeWorld(clone).isEmpty(),"Donor losses persist after respawn");h.succeed();}
    @GameTest(template="empty") public static void activeProviderUnlocksBothIdentitiesWithoutUnkeyingAndRevokesOnRemoval(GameTestHelper h){var p=player(h);var donor=UUID.randomUUID();var friend=UUID.randomUUID();var stored=new StolenConnection(donor,"sel",Map.of(friend,40.));var keyed=new ItemStack(Items.IRON_INGOT);Metalminds.transfer(keyed,donor,"iron",20);var own=new ItemStack(Items.IRON_INGOT);Metalminds.transfer(own,p.getUUID(),"iron",20);try{h.assertTrue(!Metalminds.usableBy(keyed,p,"iron"),"Foreign keyed mind initially denied");IMPLANTED.put(p,List.of(stored));h.assertTrue(Metalminds.usableBy(keyed,p,"iron")&&Metalminds.usableBy(own,p,"iron"),"Native and implanted Identities both authorize");h.assertTrue(Metalminds.transferFor(keyed,p,"iron",-1)==-1&&Metalminds.owner(keyed).equals(donor)&&!Metalminds.unkeyed(keyed),"Tapping preserves original ownership and keyed status");h.assertTrue(IdentityAccess.worlds(p).contains("sel")&&IdentityAccess.bonds(p).get(friend)==40,"World and player Connection access uses the stored snapshot");AluminumSuppression.apply(p);h.assertTrue(!Metalminds.usableBy(keyed,p,"iron")&&IdentityAccess.implanted(p).isEmpty(),"Aluminum blocks borrowed power access");PowerData.data(p).putLong("hemalurgic_aluminum_until",p.server.overworld().getGameTime());IMPLANTED.remove(p);h.assertTrue(!Metalminds.usableBy(keyed,p,"iron")&&Metalminds.usableBy(own,p,"iron")&&!IdentityAccess.worlds(p).contains("sel"),"Removal immediately revokes borrowed Identity/world access while retaining own");}finally{IMPLANTED.remove(p);}h.succeed();}
    @GameTest(template="empty") public static void compoundingRequiresActualPossessionOfDonorIdentity(GameTestHelper h){var p=player(h);var donor=UUID.randomUUID();var foreign=UUID.randomUUID();PowerAttributes.set(p,"a:steel",1);EXTERNAL.put(p,Map.of("f:steel",List.of(new IdentityMath.Portion(donor,1))));try{h.assertTrue(PowerSources.pair(p,"steel").allomancy()==0,"Different source Identities cannot compound before possession");IMPLANTED.put(p,List.of(new StolenConnection(donor,"",Map.of())));var compatible=PowerSources.pair(p,"steel");h.assertTrue(compatible.allomancy()==1&&compatible.feruchemy()==1,"Native and stolen powers become compatible while the donor Identity is active");EXTERNAL.put(p,Map.of("f:steel",List.of(new IdentityMath.Portion(foreign,1))));h.assertTrue(PowerSources.pair(p,"steel").allomancy()==0,"Unrelated third-party Identity remains incompatible");EXTERNAL.put(p,Map.of("f:steel",List.of(new IdentityMath.Portion(donor,1))));IMPLANTED.remove(p);h.assertTrue(PowerSources.pair(p,"steel").allomancy()==0,"Removing Identity access stops cross-source compounding");}finally{IMPLANTED.remove(p);EXTERNAL.remove(p);}h.succeed();}
    @GameTest(template="empty") public static void canceledDeathsAndMobKillsDoNotStealConnections(GameTestHelper h){var p=player(h);var donor=player(h);new OriginData("scadrial","human","none","none").save(donor);var spike=equip(p);var e=queue(p,donor);e.setCanceled(true);HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(spike)&&IdentityAccess.nativeIdentity(donor).equals(donor.getUUID())&&IdentityAccess.nativeWorld(donor).equals("scadrial"),"Canceled death leaves player untouched");var mob=EntityType.VILLAGER.create(h.getLevel());queue(p,mob);HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(spike),"Duralumin theft is player-only");h.succeed();}
}
